        catch (error) { checkpoint = { ...checkpoint, status: "external_checkpoint_pending", findings: [...(checkpoint.findings || []), { code: error?.code || "MANIFEST_APPROVAL_LEDGER_REVOCATION_ANCHOR_FAILED" }] }; }
