      try { await reconcileCrossDomainRetentionApprovalLifecycleCheckpoint(ownerId); return await getCrossDomainRetentionApprovalLifecycleCheckpointStatus(ownerId); }
      catch (error) { return { ...status, status: "external_checkpoint_pending", findings: [...(status.findings || []), { code: error?.code || "CROSS_DOMAIN_RETENTION_APPROVAL_LIFECYCLE_ADVANCE_FAILED" }] }; }
