    const receiptIds = new Set(rows.filter(row => row?.ownerId === ownerId && row.kind === SIGNED_LEASE_EXPORT_VERIFICATION_RECEIPT_KIND).map(row => row.id));
    const approvals = rows.filter(row => row?.ownerId === ownerId && row.kind === SIGNED_LEASE_EXPORT_VERIFICATION_RECEIPT_RETENTION_REVIEW_APPROVAL_KIND);
    for (const approval of approvals) for (const ref of approval.reviewedReceiptRefs || []) if (!receiptIds.has(ref.id))
      findings.push({ code: "CROSS_DOMAIN_LEDGER_RETENTION_APPROVAL_ORPHANED_RECEIPT", approvalId: approval.id, receiptId: ref.id });
