      const fresh = decorateCrossDomainCheckpointFreshness(state);
      if (fresh.freshnessStatus === "fresh") return { ...fresh, idempotent: true, readOnly: true, mutationAllowed: false };
      if (["stale", "future_within_skew"].includes(fresh.freshnessStatus)) return service.refreshExternalSnapshotCheckpoint(ownerId);
