    if (state.status !== "behind_local") return service.reconcileExternalSnapshotCheckpoint(ownerId);
    const source = await readCrossDomainLeaseExportVerificationReceiptSnapshot(ownerId);
    if (!["healthy", "recoverable"].includes(source.status) || source.count !== state.anchoredSourceCount + 1 || !crossDomainDigest(state.anchoredSourceDigest))
      throw new AgenticError("CROSS_DOMAIN_LEASE_EXPORT_RECEIPT_CONTINUITY_UNPROVEN", "Verification-receipt checkpoint hanya dapat dimajukan satu receipt per rekonsiliasi", 409,
        { sourceStatus: source.status, sourceCount: source.count, anchoredSourceCount: state.anchoredSourceCount, findings: source.findings || [] });
    const matches = [];
