  async function advanceRecoveryIntentClosureCheckpoint(ownerId, service, sourceReader, label, operationId) {
    const current = await service.getExternalSnapshotCheckpointStatus(ownerId);
    if (current.status === "marker_pending") return service.reconcileExternalSnapshotCheckpoint(ownerId);
    if (current.status === "anchored") {
      const fresh = decorateCrossDomainCheckpointFreshness(current);
      if (fresh.freshnessStatus === "fresh" && !fresh.historyNotProven && !fresh.policyDrift)
        return { ...fresh, idempotent: true, readOnly: true, mutationAllowed: false };
      if (["stale", "future_within_skew"].includes(fresh.freshnessStatus) && !fresh.historyNotProven && !fresh.policyDrift)
        return service.refreshExternalSnapshotCheckpoint(ownerId);
    }
    if (current.status !== "behind_local" || current.policyDrift)
      throw new AgenticError("RECOVERY_INTENT_CLOSURE_CHECKPOINT_ADVANCE_BLOCKED",
        `Checkpoint ${label} tidak dapat dimajukan dari status saat ini`, 409,
        { status: current.status, policyDrift: Boolean(current.policyDrift), operationId: operationId || null, findings: current.findings || [] });
    const source = await sourceReader(ownerId);
    if (source.status !== "healthy" || source.count !== current.anchoredSourceCount + 1
      || !crossDomainDigest(current.anchoredSourceDigest || ""))
      throw new AgenticError("RECOVERY_INTENT_CLOSURE_CHECKPOINT_GAP_UNPROVEN",
        `Checkpoint ${label} hanya dapat dimajukan satu event dengan kontinuitas terbukti`, 409,
        { sourceStatus: source.status, sourceCount: source.count, anchoredSourceCount: current.anchoredSourceCount,
          operationId: operationId || null, findings: source.findings || [] });
    const matches = [];
    for (const event of source.snapshot.events || []) {
      const candidate = structuredClone(source.snapshot);
      candidate.events = candidate.events.filter(item => item.id !== event.id);
      if (candidate.events.length === current.anchoredSourceCount
        && crossDomainSha256(crossDomainCanonical(candidate)) === current.anchoredSourceDigest) matches.push(event.id);
    }
    if (matches.length !== 1) throw new AgenticError("RECOVERY_INTENT_CLOSURE_CHECKPOINT_CONTINUITY_UNPROVEN",
      `Kontinuitas checkpoint ${label} tidak dapat dibuktikan secara unik`, 409, { matchingEventIds: matches });
    return service.reconcileExternalSnapshotCheckpoint(ownerId);
  }
